const WRITING_EXAMPLES: Record<string, string> = {
  p1: 'Het zware pakket van Noor staat op de stoep. Op de stoep staat het zware pakket van Noor. Ik heb de plaatsbepaling op de stoep als één blok verplaatst. Het onderwerp blijft het zware pakket van Noor.',
  p2: 'De veiligheidstraining is maandag om 9.00 uur in zaal B. De lezer weet nu welke activiteit plaatsvindt, wanneer die begint en waar die is. Ik heb alleen de verstrekte gegevens gebruikt en geen details toegevoegd.',
  p3: 'Op het stille perron wachtte de reiziger. De reiziger wachtte daar. De eerste zin voert de vooroptest uit; de tweede vervangt het hele blok door daar. Beide tests ondersteunen dat op het stille perron een zinsdeel vormt.',
  p4: 'Het voorstel van de bewoners is haalbaar. De kern van het onderwerp is voorstel en dat is enkelvoud. Van de bewoners geeft aan van wie het voorstel is; bewoners bepaalt hier dus niet de persoonsvorm.',
  p5: 'In Water is schaars wordt de stof in algemene zin genoemd. Een stofnaam kan zo zonder lidwoord voorkomen. Het water in deze fles wijst daarentegen een afgebakende hoeveelheid aan die de lezer via de fles kan identificeren.',
  p6: 'In een mooie, stevige tafel zijn mooi en stevig gelijkwaardige beoordelingen: een mooie en stevige tafel. In een mooie oude houten tafel geeft houten het materiaal aan en staat het dicht bij tafel. Daarom plaats ik niet automatisch tussen alle eigenschappen komma’s.',
  p7: 'De map ligt op de tafel. Ik wacht op de uitslag. In de eerste zin geeft op de tafel letterlijk de plaats aan. In de tweede hoort op bij de vaste combinatie wachten op; de uitslag is geen locatie.',
  p8: 'Leggen vraagt in deze betekenis om een voorwerp en een plaats waar dat voorwerp wordt neergelegd. Op de kast vult die plaats in. Tijdens de pauze geeft aanvullende tijdinformatie die niet speciaal door leggen wordt gevraagd. Ik combineer dus de betekenis van het werkwoord met de weglaattest.',
  p10: 'Het rapport is beschikbaar. Verschillende onafhankelijke onderzoekers hebben het uitvoerig gecontroleerd. De kern rapport staat meteen in beeld. Alle inhoudelijke gegevens blijven behouden: verschillende onderzoekers, hun onafhankelijkheid en de uitvoerige controle. De tweede zin werkt de eerste uit.',
  p11: 'De cursus leert je kritisch lezen, drogredenen herkennen en een betoog schrijven. Elk onderdeel bestaat nu uit een infinitiefgroep. Ik heb het herkennen van en hoe je een betoog schrijft vervangen, zodat de drie onderdelen grammaticaal parallel zijn.',
  p12: 'Trots is de bijvoeglijke kern. Op haar team is de aanvulling die aangeeft waarop de trots gericht is. Erg geeft de graad aan. In de hier gebruikte X-bar-analyse komen trots en op haar team eerst samen; erg wordt aan die tussenlaag toegevoegd.',
  p13: 'Met behulp van mijn drone fotografeerde ik de vrouw. Ik fotografeerde de vrouw die een drone bij zich had. In de eerste zin is de drone mijn instrument; in de tweede hoort hij als bezit bij de vrouw.',
  p14: 'In de eerste zin volstaat elke geschikte vertaler: de spreker heeft geen bepaald individu nodig. In de tweede verwijst de spreker naar een vertaler die eerder is ontmoet. Het lidwoord een blijft in beide zinnen onbepaald, maar de tweede verwijzing is specifiek bedoeld.',
  p15: 'Alle medewerkers lezen hetzelfde rapport. Iedere medewerker kiest zelf een rapport om te lezen. De eerste versie verplicht één gezamenlijk rapport. De tweede laat verschillende rapporten toe, zonder te eisen dat ieder daadwerkelijk een ander exemplaar kiest.',
  p16: 'Een goede pianist speelt goed piano. Dat zegt op zichzelf niets over morele eigenschappen. Een goed mens is een morele beoordeling. De conclusie wisselt dus ongemerkt van betekenis van goed, zonder bewijs dat de twee beoordelingen samenvallen.',
  p17: 'Zwarte markt kan een vaste overdrachtelijke betekenis hebben, maar wordt toch als twee woorden geschreven. Een bijzondere betekenis is dus niet genoeg om één samengesteld woord aan te nemen. Je onderzoekt ook de vorm en controleert zo nodig de conventionele spelling.',
  p18: 'De raad vergaderde drie uur over de gevolgen voor het verkeer. Daarna besloot de raad het plan uit te stellen. De hoofdhandelingen vergaderde en besloot staan vroeg. Daarna bewaart de tijdsvolgorde; de gevolgen voor het verkeer blijven het onderwerp van de vergadering.',
  z1: 'Noor bespreekt morgen het plan. Morgen bespreekt Noor het plan. Bespreekt Noor morgen het plan? Bespreekt is steeds de persoonsvorm. In de mededelingen volgt die op het eerste zinsdeel; in de ja-neevraag staat die vooraan.',
  z2: 'De bibliotheek opent een nieuwe studiezaal. Die zaal biedt twintig stille werkplekken. Studenten kunnen er vanaf maandag terecht. Ik begin de tweede zin met die zaal om de eerder genoemde studiezaal weer op te pakken. Daardoor sluit de nieuwe informatie aan op wat al bekend is.',
  z3: 'De workshop begint zaterdag om 10.00 uur. Kun je erbij zijn? Neem een pen, papier en je laptop mee. De punt sluit de mededeling af. Het vraagteken markeert de directe vraag. De komma scheidt de eerste twee onderdelen van de opsomming; vóór en is hier geen komma nodig.',
  s1: 'Ik bel mijn collega omdat de trein vertraging heeft. Hoewel de trein vertraging heeft, bereik ik de afspraak op tijd. Als de vertraging verder oploopt, meld ik dat opnieuw. Omdat geeft de reden voor het bellen, hoewel een onverwachte uitkomst en als een voorwaarde voor een nieuwe melding.',
  s2: 'Omdat de trein vertraging heeft, begin ik het gesprek later. Na het gesprek stuur ik het verslag. Mijn collega, die vandaag notuleert, controleert de samenvatting. De eerste komma markeert een bijzingrens. Na de korte woordgroep in de tweede zin is geen komma nodig. De twee komma’s in de derde zin bakenen extra informatie af.',
  s3: 'Kun je de ontbrekende tabel met de maandresultaten uiterlijk morgen om 11.00 uur toesturen? Ik heb die nodig om het verslag af te maken. Laat het vandaag vóór 16.00 uur weten als die termijn niet haalbaar is, zodat we een andere afspraak kunnen maken.',
  a1: 'Een vaste stille werkplek zou mij helpen om geconcentreerd te studeren. Op die plek kan ik mijn materiaal klaarleggen en meldingen uitschakelen. Zo kan ik bijvoorbeeld een moeilijk hoofdstuk lezen zonder tussendoor mijn spullen te verplaatsen. Dat werkt alleen als huisgenoten weten wanneer ik ongestoord wil werken. Ik wil daarom vooraf afspraken maken over het gebruik van die plek.',
  a2: 'Ons team verschuift het overleg van maandag naar dinsdag. Die afspraak komt in het gedeelde rooster te staan. Door de wijziging kan Noor aanwezig zijn. Dat maakt het eenvoudiger om haar vragen meteen te bespreken. Toch moet Sam zijn andere afspraak verzetten. Die afspraak verwijst naar het overleg op dinsdag. Dat verwijst naar de mogelijkheid dat Noor bij het overleg aanwezig is. Toch introduceert een nadeel naast dat voordeel.',
};

// De inhoudelijke zelfcheck gebruikt de concrete doelen van de les; woordherkenning
// alleen kan de kwaliteit van een vrije formulering niet vaststellen.
for (const [lessonId, upgrade] of Object.entries(WRITING_UPGRADES)) {
  for (const step of upgrade.steps) {
    if (step.kind === 'write') {
      step.rubric = {
        criteria: ['Mijn tekst voert alle onderdelen van de opdracht uit.', ...upgrade.guidance.selfCheck],
        example: WRITING_EXAMPLES[lessonId] ?? step.why,
      };
    }
  }
}
